import * as React from "react";
import {Icon,type IconProps} from "@/components/ui/icon";

export type UnlinkIconProps=Omit<IconProps,"name">;
/** Lucide "unlink" through the Cojeev Icon: motion presets, sizes and feedback included. */
export function UnlinkIcon(props:UnlinkIconProps){return <Icon name="unlink" {...props}/>;}
